        assertFalse(getBooleanField(effDeny, "effect"));
        assertEquals( -1, getIntField(effDeny, "explainIndex"));

        DefaultStreamEffector effAllow = new DefaultStreamEffector("!some(where (p_eft == deny))");
        effAllow.push(Effect.Allow, 2, 8);

