        DefaultStreamEffector eff = new DefaultStreamEffector("some(where (p_eft == allow)) && !some(where (p_eft == deny))");
        eff.push(Effect.Allow, 4, 9);

        // After Allow, explainIndex should be set to currentIndex (4) since initial is -1
        assertTrue(getBooleanField(eff, "done"));
        assertTrue(getBooleanField(eff, "effect"));
        assertEquals(4, getIntField(eff, "explainIndex"));

        DefaultStreamEffector effDeny = new DefaultStreamEffector("some(where (p_eft == allow)) && !some(where (p_eft == deny))");
