public class MustUseDispatcherTests {

    private CoreEnforcer createCoreEnforcer() throws Exception {
        Class<?> cls = CoreEnforcer.class;
        Constructor<?> ctr = null;

        // Try to find a no-arg constructor first
        for (Constructor<?> c : cls.getDeclaredConstructors()) {
            if (c.getParameterCount() == 0) {
                ctr = c;
                break;
            }
        }

        // If not found, pick a constructor that only has reference types (no primitives)
        if (ctr == null) {
            for (Constructor<?> c : cls.getDeclaredConstructors()) {
                Class<?>[] params = c.getParameterTypes();
                boolean allRef = params.length > 0;
                for (Class<?> t : params) {
                    if (t.isPrimitive()) {
                        allRef = false;
                        break;
                    }
                }
                if (allRef) {
                    ctr = c;
                    break;
                }
            }
        }

        if (ctr == null) {
            throw new RuntimeException("No suitable constructor found for CoreEnforcer");
        }

        ctr.setAccessible(true);
        Class<?>[] paramTypes = ctr.getParameterTypes();
        Object[] args = new Object[paramTypes.length];
        for (int i = 0; i < paramTypes.length; i++) {
