public class AddLinkTests {

    // FakeRoleManager to capture addLink calls without implementing full RBAC logic
    public static class FakeRoleManager extends DefaultRoleManager {
        public List<String> calls = new ArrayList<>();

        public FakeRoleManager() {
            super(0);
        }

        @Override
        public void addLink(String name1, String name2, String... domain) {
            String dom = "";
            if (domain != null && domain.length > 0) {
                dom = ":" + Arrays.toString(domain);
            }
            calls.add(name1 + "," + name2 + dom);
        }
    }

    // TestDomainManager overrides getRoleManager and sets up a mock rmMap
    public static class TestDomainManager extends DomainManager {
        public FakeRoleManager rmA;
        public FakeRoleManager rmB;
        public FakeRoleManager rmC;

        public TestDomainManager(int maxHierarchyLevel,
                               BiPredicate<String, String> matchingFunc,
                               BiPredicate<String, String> domainMatchingFunc) {
            super(maxHierarchyLevel, matchingFunc, domainMatchingFunc);
            // Initialize rmMap with fake role managers
            this.rmMap.clear();
            rmA = new FakeRoleManager();
            rmB = new FakeRoleManager();
            rmC = new FakeRoleManager();
            this.rmMap.put("domainA", rmA);
            this.rmMap.put("domainB", rmB);
            this.rmMap.put("domainC", rmC);
        }

        @Override
        protected DefaultRoleManager getRoleManager(String domain, boolean createIfNotExists) {
            // Return corresponding fake RM for the given domain
            DefaultRoleManager rm = this.rmMap.get(domain);
            if (rm == null) {
                rm = new FakeRoleManager();
                this.rmMap.put(domain, rm);
            }
            return rm;
